export type Method = 'local' | 'network'

export function parseMethod(methodString: string): Method {
  switch (methodString) {
    case 'local':
      return 'local'
    case 'network':
      return 'network'
    default:
      throw new Error(`Invalid method string: ${methodString}`)
  }
}

import {debug} from '@actions/core'
import os from 'os'

export enum OSType {
  windows = 'windows',
  linux = 'linux'
}

export async function getOs(): Promise<OSType> {
  const osPlatform = os.platform()
  switch (osPlatform) {
    case 'win32':
      return OSType.windows
    case 'linux':
      return OSType.linux
    default:
      debug(`Unsupported OS: ${osPlatform}`)
      throw new Error(`Unsupported OS: ${osPlatform}`)
  }
}

export async function getRelease(): Promise<string> {
  return os.release()
}

import * as core from '@actions/core'
import {exec} from '@actions/exec'

export async function execReturnOutput(
  command: string,
  args: string[] = []
): Promise<string> {
  let result = ''
  const execOptions = {
    listeners: {
      stdout: (data: Buffer) => {
        result += data.toString()
      },
      stderr: (data: Buffer) => {
        core.debug(`Error: ${data.toString()}`)
      }
    }
  }
  const exitCode = await exec(command, args, execOptions)
  if (exitCode) {
    core.debug(`Error executing: ${command}. Exit code: ${exitCode}`)
  }
  return result.trim()
}

import * as core from '@actions/core'
import {OSType, getOs} from './platform'
import {AbstractLinks} from './links/links'
import {Method} from './method'
import {SemVer} from 'semver'
import {WindowsLinks} from './links/windows-links'
import {getLinks} from './links/get-links'

// Helper for converting string to SemVer and verifying it exists in the links
export async function getVersion(
  versionString: string,
  method: Method
): Promise<SemVer> {
  const version = new SemVer(versionString)
  const links: AbstractLinks = await getLinks()
  let versions
  switch (method) {
    case 'local':
      versions = links.getAvailableLocalCudaVersions()
      break
    case 'network':
      switch (await getOs()) {
        case OSType.linux:
          // TODO adapt this to actual available network versions for linux
          versions = links.getAvailableLocalCudaVersions()
          break
        case OSType.windows:
          versions = (links as WindowsLinks).getAvailableNetworkCudaVersions()
          break
      }
  }
  core.debug(`Available versions: ${versions}`)
  if (versions.find(v => v.compare(version) === 0) !== undefined) {
    core.debug(`Version available: ${version}`)
    return version
  } else {
    core.debug(`Version not available error!`)
    throw new Error(`Version not available: ${version}`)
  }
}
